"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["82808"],{61645(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.cardinalidade_invalida","status":422,"titulo":"Cardinalidade do fato fora do vocabul\xe1rio fechado"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.cardinalidade_invalida","requisitos":["UNI-REQ-0143","UNI-REQ-0159"],"oQueAconteceu":["O administrador cadastrou um fato declarado (`POST /api/configuracao/admin/fatos-candidato`) ou alterou a defini\xe7\xe3o de um fato (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`) com uma `cardinalidade` que n\xe3o pertence ao vocabul\xe1rio fechado. A cardinalidade diz se o fato aceita uma resposta ou v\xe1rias (UNI-REQ-0143 e UNI-REQ-0159). A compara\xe7\xe3o diferencia mai\xfasculas de min\xfasculas, e os espa\xe7os nas pontas s\xe3o desconsiderados.","A recusa vem na lista `errors` da resposta, com `field` igual a `cardinalidade`. Nada \xe9 gravado. Um campo vazio ou s\xf3 com espa\xe7os n\xe3o cai aqui: no cadastro e na altera\xe7\xe3o de um fato declarado, ele recebe [a recusa de cardinalidade obrigat\xf3ria](/erros/uniplus.configuracao.fato_candidato.cardinalidade_obrigatoria); na altera\xe7\xe3o de um fato derivado ou resumo de grupo, o vazio \xe9 tratado como n\xe3o informado e n\xe3o \xe9 recusado.","No fato de sistema, que s\xf3 aceita mudar o nome, a descri\xe7\xe3o, a forma de exibi\xe7\xe3o e a prote\xe7\xe3o de dados, a cardinalidade fora do vocabul\xe1rio tamb\xe9m recebe esta recusa, antes da recusa de [defini\xe7\xe3o do fato de sistema travada](/erros/uniplus.configuracao.fato_candidato.definicao_do_fato_de_sistema_travada)."],"comoResolver":["Envie uma destas cardinalidades, escrita exatamente assim, em mai\xfasculas:","- `VALOR_UNICO`: o fato tem uma \xfanica resposta;\\n- `VARIOS_VALORES`: o fato aceita v\xe1rias respostas.","O fato derivado por regra e o resumo de grupo n\xe3o informam a cardinalidade: ela \xe9 inferida do tipo de dado, e quem a envia recebe [a recusa de eixo que o tipo do fato n\xe3o permite alterar](/erros/uniplus.configuracao.fato_candidato.eixo_nao_editavel_no_tipo_do_fato)."],"ondeAparece":["Cadastro de um fato declarado do cat\xe1logo","Altera\xe7\xe3o da defini\xe7\xe3o de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);